pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(new __InvMutHandleStub())); }
    function testFuzz_property(bytes32 assertionId) public {
        BaseEscalationManager.AssertionPolicy memory p = c.getAssertionPolicy(assertionId);
        assertTrue(
            !p.blockAssertion && !p.arbitrateViaEscalationManager && !p.discardOracle && !p.validateDisputers,
            "policy flags must all be false"
        );
    }
}
